mapper.select:
SELECT rp.id AS id, rp.role_id AS roleId, r.role_name AS roleName, r.user_id AS ownerUserId, COALESCE(NULLIF(u.realname, ''), u.username) AS ownerDisplayName, rp.channel_code AS channelCode, c.channel_name AS channelName, rp.status AS status, rp.display_title AS displayTitle, rp.display_subtitle AS displaySubtitle, rp.cover_image_url AS coverImageUrl, rp.intro_text AS introText, rp.sort_order AS sortOrder, rp.published_at AS publishedAt, rp.offline_at AS offlineAt, rp.reject_reason AS rejectReason, rp.ext_json AS extJson, rp.create_time AS createTime, rp.update_time AS updateTime FROM ts_role_public rp INNER JOIN ts_role_info r ON r.id = rp.role_id LEFT JOIN ts_public_channel c ON c.channel_code = rp.channel_code LEFT JOIN sys_user u ON u.id = r.user_id WHERE (r.status IS NULL OR r.status != 0)
AND ( r.role_name LIKE CONCAT('%', #{query.keyword}, '%') OR rp.display_title LIKE CONCAT('%', #{query.keyword}, '%') OR rp.intro_text LIKE CONCAT('%', #{query.keyword}, '%') )
AND rp.channel_code = #{query.channelCode}
AND rp.status = #{query.status}
AND r.user_id = #{query.ownerUserId}
ORDER BY rp.sort_order ASC, rp.update_time DESC, rp.id DESC

SELECT r.id AS id, rp.id AS publicId, rp.channel_code AS channelCode, COALESCE(NULLIF(rp.display_title, ''), r.role_name) AS roleName, COALESCE(NULLIF(rp.display_subtitle, ''), r.role_subtitle) AS roleSubtitle, r.avatar_url AS avatarUrl, COALESCE(NULLIF(rp.cover_image_url, ''), r.cover_url) AS coverUrl, r.gender AS gender, r.occupation AS occupation, COALESCE(NULLIF(rp.intro_text, ''), r.greeting) AS introText, COALESCE(NULLIF(u.realname, ''), u.username) AS authorName, u.avatar AS authorAvatar, r.updated_at AS updatedAt FROM ts_role_public rp INNER JOIN ts_role_info r ON r.id = rp.role_id LEFT JOIN sys_user u ON u.id = r.user_id WHERE rp.status = 'online' AND (r.status IS NULL OR r.status != 0) AND r.review_status = 'APPROVED'
AND rp.channel_code = #{query.channelCode}
AND ( r.role_name LIKE CONCAT('%', #{query.keyword}, '%') OR r.role_subtitle LIKE CONCAT('%', #{query.keyword}, '%') OR rp.display_title LIKE CONCAT('%', #{query.keyword}, '%') OR rp.intro_text LIKE CONCAT('%', #{query.keyword}, '%') )
AND r.gender = #{query.gender}
ORDER BY rp.sort_order ASC, rp.published_at DESC, rp.id DESC

SELECT r.id AS id, rp.id AS publicId, rp.channel_code AS channelCode, COALESCE(NULLIF(rp.display_title, ''), r.role_name) AS roleName, COALESCE(NULLIF(rp.display_subtitle, ''), r.role_subtitle) AS roleSubtitle, r.avatar_url AS avatarUrl, COALESCE(NULLIF(rp.cover_image_url, ''), r.cover_url) AS coverUrl, r.gender AS gender, r.occupation AS occupation, COALESCE(NULLIF(rp.intro_text, ''), r.greeting) AS introText, r.greeting AS greeting, r.background_story AS backgroundStory, r.dialogue_preview AS dialoguePreview, r.dialogue_length AS dialogueLength, r.tone_tendency AS toneTendency, r.interaction_mode AS interactionMode, r.voice_name AS voiceName, COALESCE(NULLIF(u.realname, ''), u.username) AS authorName, u.avatar AS authorAvatar, COALESCE(st.connector_count, 0) AS connectorCount, COALESCE(st.follower_count, 0) AS followerCount, COALESCE(st.dialogue_count, 0) AS dialogueCount, r.updated_at AS updatedAt FROM ts_role_public rp INNER JOIN ts_role_info r ON r.id = rp.role_id LEFT JOIN sys_user u ON u.id = r.user_id LEFT JOIN ts_role_stat st ON st.role_id = r.id WHERE rp.status = 'online' AND (r.status IS NULL OR r.status != 0) AND r.review_status = 'APPROVED'
AND r.id = #{id}
AND rp.id = #{publicId}
AND rp.channel_code = #{channelCode}
ORDER BY rp.published_at DESC, rp.id DESC LIMIT 1
